// Individual mixins using CRTP:
template<typename Derived>
struct NamedMixin {
    string name;
    string getName() const {
        return static_cast<const Derived&>(*this).name;
    }
};

template<typename Derived>
struct ComparableMixin {
    bool operator!=(const Derived& other) const {
        return !static_cast<const Derived&>(*this)
                    .operator==(other);
    }
};

// Compose by inheriting multiple CRTP mixins:
class Person : public NamedMixin<Person>,
               public ComparableMixin<Person> {
public:
    Person(string n, int a) : name(move(n)), age(a) {}
    bool operator==(const Person& other) const {
        return name == other.name && age == other.age;
    }
    string name;
    int age;
};

