// Apply a function to each element of an array at compile time:
template<typename T, size_t N, typename F, size_t... I>
constexpr void forEachImpl(T (&arr)[N], F func, index_sequence<I...>) {
    (func(arr[I]), ...);  // fold expression (C++17)
}

template<typename T, size_t N, typename F>
constexpr void forEach(T (&arr)[N], F func) {
    forEachImpl(arr, func, make_index_sequence<N>{});
}

// C++23: deducing 'this' in lambdas for recursion
// without std::function overhead: 
auto fibonacci = [](this auto self, int n) -> int {
    if (n <= 1) return n;
    return self(n-1) + self(n-2);
};

cout << fibonacci(10);  // 55

// Also useful for method chaining:
auto counter = [](this auto self, int start = 0) {
    struct Impl {
        int val;
        Impl& inc() { ++val; return *this; }
        Impl& dec() { --val; return *this; }
    };
    return Impl{start};
};

auto c = counter(5).inc().inc().dec();
cout << c.val;  // 6
